mapper.select:
SELECT /* LGVPAY00021.retrieveCalcSetList */ pcs.payroll_calculation_set_id , pcs.payroll_calculation_set_name , pcs.resignation_flag , pcs.payroll_type_code ,(SELECT lgvhr_common_pkg.decode_lookup('LGVHR_PAY_RUN_TYPE', pcs.payroll_type_code, NULL, #{USER_SESSION.languageCode}) FROM DUAL) AS payroll_type_name , pcs.object_type -- vanaa 03/11/2025 , pcs.auto_creation_flag
,(SELECT COUNT(cstp.employee_no) FROM tb_pay_calc_set_target_per_n cstp WHERE cstp.payroll_calculation_set_id = pcs.payroll_calculation_set_id) AS set_person_count /* Calculation Set 대상자 인원수 */
,(SELECT CASE WHEN COUNT(pce.payroll_calculation_exec_id) > 0 THEN 'Y' ELSE 'N' END FROM tb_pay_calc_exec_n pce , tb_pay_calc_emp_exec_n pcee WHERE pce.payroll_calculation_set_id = pcs.payroll_calculation_set_id AND pcee.payroll_calculation_exec_id(+) = pce.payroll_calculation_exec_id) AS exec_flag /* 급여 실행되었는지 여부 */
FROM tb_pay_calc_set_n pcs WHERE pcs.subsidiary_code = #{LGVHR_PROJECT_SESSION.subsidiaryCode} AND pcs.payroll_calculation_set_name like #{calculationSetName}||'%'
AND pcs.payroll_calculation_set_id = #{srchPayrollCalculationSetId, jdbcType=NUMERIC}
/* calculation_set_name이 mm/yyyy 형태이므로, yyyymm 형태로 변환하여 정렬 */ ORDER BY REGEXP_REPLACE(pcs.payroll_calculation_set_name,'([[:digit:]]{2})\/([[:digit:]]{4})','\2/\1')
